.card {
  width: 100%; aspect-ratio: 1; min-width: 44px; min-height: 44px;
  position: relative; display: grid; place-items: center; padding: 0;
  border: 2px solid var(--border); border-radius: 8px; background: var(--back);
  color: var(--secondary); cursor: pointer; transition: border-color 120ms;
  scroll-margin: 6px; touch-action: manipulation;
}
.card:hover { border-color: var(--text); }
.card.revealed { background: var(--face); }
.card.matched, .card.matched:hover { border-color: var(--green); opacity: 1; }
.card:focus-visible { outline: 3px solid #FFFFFF; outline-offset: 2px; z-index: 1; }
.card-back { font-size: 28px; font-weight: 400; line-height: 1; }
.face { display: block; width: 100%; height: 100%; }
.card-check { position: absolute; right: 4px; bottom: 0; color: var(--green); font-size: 12px; line-height: 16px; }
@media (prefers-reduced-motion: reduce) { .card { transition: none; } }

